import{_ as r,o as t,c as l,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Performance Meeting 2018-11-15","description":"","frontmatter":{"title":"Ceph Performance Meeting 2018-11-15","date":"2018-11-15T00:00:00.000Z","updated":"2018-11-16T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","BlueStore","RocksDB","缓存"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/Ceph_Performance_Meeting_2018-11-15.md","filePath":"posts/2018/Ceph_Performance_Meeting_2018-11-15.md","lastUpdated":1780459816000}'),s={name:"posts/2018/Ceph_Performance_Meeting_2018-11-15.md"};function i(n,e,p,g,u,a){return t(),l("div",null,[...e[0]||(e[0]=[o("<p><strong>会议纪要</strong></p><p><strong>会议时间</strong>： 2018年11月15日</p><p><strong>参会人员</strong>： Radek、Alex、Ben、Jesse等</p><p><strong>会议主题</strong>： Ceph存储项目性能优化进展及讨论</p><p><strong>会议内容</strong>：</p><p><strong>一、Ceph项目性能优化进展</strong></p><ul><li><strong>Radek</strong>： <ul><li>优化buffer管理，移除pen buffer，减少不必要的原子操作。</li><li>开发hyper combined buffers，提高buffer列表迭代效率。</li><li>处理RDMA相关工作，提升性能。</li><li>优化EC striped cache功能。</li><li>开发auto-tuner改进方案，优化BlueStore缓存行为。</li></ul></li><li><strong>Alex</strong>： <ul><li>进行BlueStore性能测试，分析读写性能。</li><li>发现read ahead机制可能影响测试结果。</li><li>分析小随机写性能问题，探讨优化方案。</li></ul></li><li><strong>Ben</strong>： <ul><li>分析BlueStore性能测试结果，探讨优化方向。</li><li>探讨RocksDB调优方案，优化小随机写性能。</li><li>开发VLA优化方案，减少内存拷贝。</li></ul></li><li><strong>Jesse</strong>： <ul><li>完成GW的VLA优化工作。</li></ul></li></ul><p><strong>二、讨论的主要议题</strong></p><ul><li><strong>buffer优化</strong>： 讨论了优化buffer管理，减少不必要的原子操作，提高效率。</li><li><strong>hyper combined buffers</strong>： 开发hyper combined buffers，提高buffer列表迭代效率。</li><li><strong>RDMA优化</strong>： 提升RDMA性能。</li><li><strong>EC striped cache优化</strong>： 优化EC striped cache功能。</li><li><strong>BlueStore性能优化</strong>： 分析BlueStore性能测试结果，探讨优化方向，包括read ahead机制、RocksDB调优等。</li><li><strong>VLA优化</strong>： 开发VLA优化方案，减少内存拷贝。</li></ul><p><strong>三、决定的事项</strong></p><ul><li>继续推进Radek的buffer优化和hyper combined buffers开发。</li><li>进一步分析Alex的BlueStore性能测试结果，确定优化方案。</li><li>探索RocksDB调优方案，优化小随机写性能。</li><li>完成Jesse的VLA优化工作。</li></ul><p><strong>四、后续行动计划</strong></p><ul><li><strong>Radek</strong>： 完成buffer优化和hyper combined buffers开发。</li><li><strong>Alex</strong>： 继续进行BlueStore性能测试，分析测试结果，确定优化方案。</li><li><strong>Ben</strong>： 分析RocksDB调优方案，优化小随机写性能。</li><li><strong>Jesse</strong>： 完成VLA优化工作。</li></ul><p><strong>五、其他事项</strong></p><ul><li>下周将不召开会议，因为感恩节假期。</li></ul><p><strong>总结</strong>：</p><p>本次会议重点讨论了Ceph存储项目的性能优化进展，涵盖了buffer优化、hyper combined buffers、RDMA优化、EC striped cache优化、BlueStore性能优化和VLA优化等多个议题。会议明确了后续行动计划，为Ceph存储项目的进一步发展奠定了基础。</p>",17)])])}const d=r(s,[["render",i]]);export{c as __pageData,d as default};
